import ast
import os
import sys
import argparse

def is_interesting_file(path):
    exclude_dirs = {'.git', '.venv', 'venv', '__pycache__', 'build', 'dist', 'docs', 'examples', 'tests', 'test', 'benchmarks'}
    parts = path.split(os.sep)
    for p in parts:
        if p in exclude_dirs:
            return False
    return path.endswith('.py')

def score_function(name, args):
    score = 0
    name = name.lower()
    interesting_keywords = ['parse', 'decode', 'load', 'deserialize', 'validate', 'convert', 'process', 'handle', 'api']

    for kw in interesting_keywords:
        if kw in name:
            score += 2

    # Simple heuristic for arguments
    if args:
        score += 1

    if name.startswith('_'):
        score -= 1 # Private functions less likely to be entry points, but could be important

    return score

class FunctionVisitor(ast.NodeVisitor):
    def __init__(self, filepath):
        self.filepath = filepath
        self.functions = []

    def visit_FunctionDef(self, node):
        score = score_function(node.name, node.args.args)
        if score > 0:
            self.functions.append({
                'name': node.name,
                'file': self.filepath,
                'lineno': node.lineno,
                'score': score,
                'args': [a.arg for a in node.args.args]
            })
        self.generic_visit(node)

    def visit_AsyncFunctionDef(self, node):
        self.visit_FunctionDef(node)

def analyze_library(lib_path):
    print(f"Analyzing {lib_path}...")
    all_functions = []

    for root, dirs, files in os.walk(lib_path):
        # Modify dirs in-place to skip ignored directories
        dirs[:] = [d for d in dirs if d not in {'.git', '.venv', 'venv', '__pycache__', 'build', 'dist', 'docs', 'examples', 'tests', 'test', 'benchmarks', '.github'}]

        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                # print(f"Parsing {filepath}")
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        tree = ast.parse(f.read(), filename=filepath)
                    visitor = FunctionVisitor(filepath)
                    visitor.visit(tree)
                    all_functions.extend(visitor.functions)
                except Exception as e:
                    # print(f"Error parsing {filepath}: {e}")
                    pass

    # Sort by score
    all_functions.sort(key=lambda x: x['score'], reverse=True)

    print("\nTop Candidates:")
    for func in all_functions[:20]:
        print(f"Function: {func['name']}")
        print(f"  File: {func['file']}")
        print(f"  Line: {func['lineno']}")
        print(f"  Score: {func['score']}")
        print(f"  Args: {func['args']}")
        print("-" * 20)

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python analyze_lib.py <lib_path>")
        sys.exit(1)

    analyze_library(sys.argv[1])

